import {MODULES,TECHS,MISSIONS,SECTORS,CREW_POOL,ACHIEVEMENTS,CONTRACTS,RESOURCE_NAMES} from './content.mjs';
import {createGame,economy,caps,build,buildSites,upgrade,upgradeCost,recycle,assign,hire,hireCost,research,sendExpedition,expeditionCapacity,expeditionDuration,crewAway,crewAssignment,housing,morale,missionProgress,claimMission,currentEvent,chooseEvent,trade,deliverContract,canAfford,awardSalvage,salvageReady,advance,serialize,restore,offlineProgress} from './engine.mjs';
import {icon,resourceIcon,moduleIcon,portrait,StationRenderer} from './art.mjs';
import {Soundscape} from './audio.mjs';
import {SalvageRun} from './salvage.mjs';
import {SocialUI} from './social-ui.mjs';

const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:d}).format(Number.isFinite(n)?n:0);
const compact=n=>n>=1000000?num(n/1000000,1)+' M':n>=10000?num(n/1000,1)+' k':num(n);
const duration=n=>{n=Math.max(0,Math.ceil(n));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
const KEY='sternenhafen.save.v1',BACKUP=KEY+'.backup',PREFS='sternenhafen.prefs.v1';
let game,hasSave=false,started=false,loadWarning='',storageOkay=true,buildGroup='all',buildType=null,selectedId=null,panel=null,salvageRun=null,pendingImport=null,recycleId=null;
let lastSave=0,lastUI=0,lastMission='',lastVisitor='',lastFlights='',lastContracts='',lastCrew='',lastTechCount=-1,lastFrame=performance.now();
let prefs={sound:false};try{prefs.sound=JSON.parse(localStorage.getItem(PREFS)||'{}').sound===true;}catch{}
try{const saved=localStorage.getItem(KEY);if(saved){try{game=restore(saved);hasSave=true;}catch{const backup=localStorage.getItem(BACKUP);if(backup){try{game=restore(backup);hasSave=true;loadWarning='Der letzte Spielstand war beschädigt. Dein vorheriger Sicherungsstand wurde wiederhergestellt.';}catch{loadWarning='Die gespeicherten Sicherungsstände sind nicht lesbar. Du kannst eine exportierte Datei importieren oder eine neue Station gründen.';}}else{loadWarning='Der gespeicherte Stand war nicht lesbar. Er bleibt als Datei im Browser erhalten, bis du eine neue Station gründest.';}}}}catch{storageOkay=false;loadWarning='Dein Browser erlaubt hier keine dauerhafte Speicherung. Du kannst spielen und deinen Stand jederzeit in den Einstellungen exportieren.';}
game??=createGame();
const socialUI=new SocialUI({getGame:()=>game,isStarted:()=>started,onOpen:()=>openPanel('social'),onRerender:()=>{if(panel==='social')renderPanel();},toast,beforeShare:()=>save(true)});
const sound=new Soundscape(prefs.sound);
const renderer=new StationRenderer($('#station-canvas'),{
  getState:()=>game,
  onSelect:m=>{selectedId=m?.id||null;renderInspector();},
  onBuild:(type,x,y)=>placeModule(type,x,y),
  onCancel:()=>cancelBuild(),
  onHover:m=>{if(!m){$('#viewport-caption').innerHTML='<span class="orbit-dot"></span>Ein kleiner Anfang in einem großen Universum.';return;}if(buildType)$('#viewport-caption').textContent='Feld '+m.x+' / '+m.y+' · Pfeiltasten + Eingabe oder klicken zum Bauen';else if(m.type)$('#viewport-caption').textContent=MODULES[m.type].name+' · Stufe '+m.level+' · Anklicken für Details';}
});

function costHTML(cost,{gain=false,sign=false}={}){return Object.entries(cost||{}).filter(([,n])=>n>0).map(([key,n])=>'<span class="cost-part '+key+'"'+(!gain?' data-resource-key="'+key+'" data-amount="'+n+'"':'')+' title="'+esc(RESOURCE_NAMES[key])+'">'+resourceIcon(key)+(sign?'+':'')+num(n,Number.isInteger(n)?0:1)+'</span>').join('');}
function costAttr(cost){return encodeURIComponent(JSON.stringify(cost||{}));}
function affordAttrs(cost,blocked=false){return 'class="small-button afford-button" data-cost="'+costAttr(cost)+'"'+(blocked?' data-blocked="true"':'')+(!canAfford(game,cost)||blocked?' disabled':'');}
function toast(title,text='',type='success'){
  const el=document.createElement('div');el.className='toast '+type;el.innerHTML=icon(type==='error'?'alert':type==='achievement'?'trophy':type==='visitor'?'ship':'spark')+'<div><strong>'+esc(title)+'</strong>'+(text?'<p>'+esc(text)+'</p>':'')+'</div>';el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label','Meldung schließen: '+title);el.addEventListener('click',()=>el.remove());el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')el.remove();});$('#toast-stack').append(el);while($('#toast-stack').children.length>4)$('#toast-stack').firstElementChild.remove();setTimeout(()=>el.remove(),type==='error'?7000:6500);$('#announcer').textContent=title+(text?'. '+text:'');
}
function drainNotices(){const notices=game.notices.splice(0);for(const n of notices){if(n.type==='victory'){openPanel('victory');sound.play('research');}else toast(n.title,n.text,n.type);}}
function save(force=false){if(!started)return false;const now=performance.now();if(!force&&now-lastSave<20000)return true;game.savedAt=Date.now();try{const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(BACKUP,previous);localStorage.setItem(KEY,serialize(game));lastSave=now;storageOkay=true;$('#save-state').textContent='Automatisch gespeichert';return true;}catch{if(storageOkay)toast('Speichern nicht möglich','Bitte exportiere deinen Stand in den Einstellungen.','error');storageOkay=false;$('#save-state').textContent='Export empfohlen';return false;}}
function changed({redrawPanel=false}={}){save(true);render(true);if(redrawPanel&&panel)renderPanel();drainNotices();}
function result(res,title,noise='build'){if(!res.ok){toast('Noch nicht ganz',res.error,'error');sound.play('error');return false;}if(title)toast(title);sound.play(noise);changed();return true;}

function renderResources(){
  if(!$('#resources').children.length){$('#resources').innerHTML=['credits','alloy','crystal','science','power','crew'].map(key=>'<div class="resource resource-'+key+'" id="resource-'+key+'"><span class="resource-icon">'+(key==='power'?icon('bolt'):key==='crew'?icon('crew'):resourceIcon(key))+'</span><div><span class="resource-name">'+({credits:'CREDITS',alloy:'LEGIERUNG',crystal:'KRISTALLE',science:'WISSEN',power:'ENERGIE',crew:'CREW & ZUHAUSE'})[key]+'</span><span class="resource-value" id="value-'+key+'"></span><span class="resource-rate" id="rate-'+key+'"></span><span class="resource-sub" id="sub-'+key+'"></span></div></div>').join('');}
  const e=economy(game),limit=caps(game);for(const key of ['credits','alloy','crystal','science']){const full=game.resources[key]>=limit[key]-.01;$('#value-'+key).innerHTML=compact(Math.floor(game.resources[key]))+(key==='alloy'||key==='crystal'?'<span class="resource-cap"> / '+compact(limit[key])+'</span>':'');$('#rate-'+key).textContent=full?'LAGER VOLL':e.rates[key]>.001?'+'+num(e.rates[key]*60,1)+'/m':'';$('#resource-'+key).title=RESOURCE_NAMES[key]+': '+num(game.resources[key],1)+(key==='alloy'||key==='crystal'?' / '+num(limit[key]):'')+' · '+num(e.rates[key],2)+' pro Sekunde';}
  $('#value-power').textContent=num(e.generated-e.demand,1);$('#rate-power').textContent='MW';$('#sub-power').textContent=num(e.demand,1)+' / '+num(e.generated,1)+' belegt';$('#resource-power').classList.toggle('warning',e.powerFactor<.999);$('#resource-power').title=e.powerFactor<1?'Energiedefizit: Produktion läuft mit '+num(e.powerFactor*100)+' %. Baue ein Solarsegel.':'Energieüberschuss: '+num(e.generated-e.demand,1)+' MW';
  $('#value-crew').innerHTML=game.crew.length+'<span class="resource-cap"> / '+housing(game)+'</span>';$('#rate-crew').textContent='♡ '+num(e.morale)+' %';$('#sub-crew').textContent=e.idle+' frei · '+game.expeditions.length+' unterwegs';$('#resource-crew').title=game.crew.length+' Crew / '+housing(game)+' Wohnplätze · '+e.idle+' ohne Arbeitsplatz · Stimmung '+e.morale+' %';
  $('#station-status').classList.toggle('warning',e.powerFactor<1);$('#station-status').innerHTML='<i></i>'+(e.powerFactor<1?'Mehr Energie wäre gut':e.idle===0&&game.modules.some(m=>MODULES[m.type].workers&&!m.assigned)?'Verstärkung wäre gut':'Alles im grünen Bereich');
  $('#cycle-label').textContent='TAG '+String(Math.floor(game.time/180)+1).padStart(2,'0');$('#chapter-label').textContent=game.won?'EIN HAFEN IN DER DUNKELHEIT':game.missionIndex<4?'KAPITEL I · EIN NEUER ANFANG':game.missionIndex<9?'KAPITEL II · DAS ALL ANTWORTET':'KAPITEL III · EIN LICHT FÜR LYRA';
  $('#salvage-status').textContent=salvageReady(game)?'Bergungsschiff bereit · Selbst fliegen':'Auftanken · Bereit in '+duration(45-(game.time-game.lastSalvage));$('#salvage-launch').setAttribute('aria-label',salvageReady(game)?'Bergungsflug starten, selbst fliegen':'Bergungsschiff tankt, noch '+duration(45-(game.time-game.lastSalvage)));
  $('#station-name').innerHTML=esc(game.name)+'<span>STATION</span>';
  $('#pause-button').innerHTML=icon(game.paused?'play':'pause');$('#pause-button').setAttribute('aria-label',game.paused?'Spiel fortsetzen':'Spiel pausieren');$('#pause-button').title=(game.paused?'Fortsetzen':'Pause')+' (Leertaste)';$$('[data-speed]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.speed)===game.speed);b.setAttribute('aria-pressed',String(Number(b.dataset.speed)===game.speed));});
  const readyResearch=TECHS.some(t=>!game.techs.includes(t.id)&&t.requires.every(id=>game.techs.includes(id))&&canAfford(game,t.cost));$('#research-dot').hidden=!readyResearch;
  if(game.paused)$('#status-text').textContent='Pause. Das Universum kann kurz warten.';else if(e.powerFactor<1)$('#status-text').textContent='Tipp: Ein Solarsegel bringt deine Produktion wieder auf volle Leistung.';else if(game.modules.some(m=>MODULES[m.type].workers&&!m.assigned))$('#status-text').textContent='Tipp: Ein Modul wartet noch auf eine Crew-Person.';else $('#status-text').textContent=game.won?'Dein Licht weist den Weg. Und die Geschichte geht weiter.':'Du bist hier genau richtig.';
}
function renderBuildList(){
  $('#build-list').innerHTML=Object.entries(MODULES).filter(([type,d])=>type!=='core'&&(buildGroup==='all'||d.group===buildGroup||d.group==='wunder')).map(([type,d])=>{const locked=d.tech&&!game.techs.includes(d.tech),exists=d.max&&game.modules.some(m=>m.type===type);return '<button class="build-item'+(locked?' locked':'')+(type===buildType?' selected':'')+'" data-build="'+type+'" aria-pressed="'+(type===buildType)+'" title="'+esc(d.description)+(locked?' Voraussetzung: '+TECHS.find(t=>t.id===d.tech).name:'')+'"'+(exists?' disabled':'')+'>'+moduleIcon(type)+'<span><span class="build-item-name">'+esc(d.name)+'</span>'+(locked?'<span class="cost-locked">'+icon('lock')+esc(TECHS.find(t=>t.id===d.tech).name)+'</span>':'<span class="build-item-cost">'+costHTML(d.cost)+'</span>')+'</span>'+(!locked&&!exists?'<i class="build-afford-dot" data-afford-dot="'+costAttr(d.cost)+'"></i>':'')+'</button>';}).join('');
}
function selectBuild(type){const d=MODULES[type];if(!d||type==='core')return;if(d.tech&&!game.techs.includes(d.tech)){openPanel('research');toast('Eine gute nächste Forschung',TECHS.find(t=>t.id===d.tech).name+' schaltet dieses Modul frei.');return;}if(d.max&&game.modules.some(m=>m.type===type)){toast('Steht schon',d.name+' ist bereits Teil deiner Station.');return;}buildType=type;selectedId=null;renderer.selected=null;renderer.buildType=type;renderer.hover=buildSites(game)[0]||null;$('#inspector').hidden=true;$('#build-hint').hidden=false;$('#build-hint').innerHTML=moduleIcon(type)+'<div><strong>'+esc(d.name)+' platzieren</strong><small>Ein markiertes Nachbarfeld wählen · Esc zum Abbrechen</small></div><button class="icon-button" data-action="cancel-build" aria-label="Bauen abbrechen">'+icon('close')+'</button>';document.body.classList.remove('mobile-build-open');closePanel();renderBuildList();if(window.innerWidth<621)$('#station').scrollIntoView({behavior:'smooth',block:'start'});$('#station-canvas').focus({preventScroll:true});}
function cancelBuild(){buildType=null;renderer.buildType=null;$('#build-hint').hidden=true;renderBuildList();}
function placeModule(type,x,y){if(!started)return;const res=build(game,type,x,y);if(!res.ok){toast('Hier noch nicht',res.error,'error');sound.play('error');return;}cancelBuild();selectedId=res.module.id;renderer.selected=selectedId;renderer.effect(x,y,'Ein Stück Zuhause.');sound.play('build');changed();renderInspector();}
function renderInspector(){const m=game.modules.find(m=>m.id===selectedId);if(!m){$('#inspector').hidden=true;return;}const d=MODULES[m.type],e=economy(game);$('#inspector').hidden=false;const worker=game.crew.find(c=>c.id===m.assigned);const max=game.techs.includes('engineering')?3:2;const upgradeable=!['core','beacon'].includes(m.type)&&m.level<max;
  $('#inspector').innerHTML='<div class="inspector-header">'+moduleIcon(m.type)+'<div><strong>'+esc(d.name)+'</strong><small>STUFE '+m.level+' / '+(m.type==='core'||m.type==='beacon'?1:max)+' · FELD '+m.x+' / '+m.y+'</small></div><button class="icon-button" data-action="close-inspector" aria-label="Modulfenster schließen">'+icon('close')+'</button></div><p>'+esc(d.description)+'</p>'+(d.workers?'<label class="sr-only" for="assign-module">Arbeitsplatz besetzen</label><select class="assign-select" id="assign-module" data-assign="'+m.id+'"><option value="">Niemand zugewiesen – Produktion steht</option>'+game.crew.filter(c=>!crewAway(game,c.id)).map(c=>'<option value="'+c.id+'"'+(c.id===m.assigned?' selected':'')+'>'+esc(c.name)+' · '+esc(c.role)+(crewAssignment(game,c.id)&&c.id!==m.assigned?' (wechselt Arbeitsplatz)':'')+'</option>').join('')+'</select>':'')+'<div class="inspector-yield">'+(d.power?'+'+num(d.power*Math.pow(1.65,m.level-1)*(m.type==='solar'&&game.techs.includes('solartech')?1.6:1),1)+' MW Energie':d.housing?'+'+(d.housing*m.level)+' Wohnplätze':d.morale?'+'+(d.morale*m.level)+' Stimmung':d.storage?'+'+(450*m.level)+' Legierung / '+(250*m.level)+' Kristalle Lager':d.produces?Object.entries(d.produces).map(([key,n])=>'+'+num(n*Math.pow(1.65,m.level-1)*60,1)+' '+RESOURCE_NAMES[key]+'/m (Basis)').join(' · '):'Ein Licht für den ganzen Sektor')+(d.workers&&!worker?' · Person zuweisen!':'')+'</div>'+(upgradeable?'<div class="cost-row">'+costHTML(upgradeCost(m))+'</div>':'')+'<div class="inspector-actions">'+(upgradeable?'<button '+affordAttrs(upgradeCost(m))+' data-upgrade="'+m.id+'">'+icon('layers')+'Auf Stufe '+(m.level+1)+'</button>':m.level===2&&!game.techs.includes('engineering')?'<button class="small-button" data-panel="research">'+icon('lock')+'Stufe 3 erforschen</button>':'')+(!['core','beacon'].includes(m.type)?'<button class="small-button danger" data-recycle="'+m.id+'">'+icon('trash')+'Recyceln</button>':'')+'</div>';
}
function missionHint(){const m=MISSIONS[game.missionIndex];if(!m){openPanel('victory');return;}if(m.kind==='module'){selectBuild(m.target);return;}openPanel(m.kind==='crew'?'crew':m.kind==='tech'?'research':'map');}
function renderMission(force=false){const m=MISSIONS[game.missionIndex],p=missionProgress(game,m),hash=game.missionIndex+':'+p.value+':'+p.complete;if(hash===lastMission&&!force)return;lastMission=hash;
  if(!m){$('#mission-card').classList.add('complete');$('#mission-card').innerHTML='<div class="mission-meta"><span>DEIN LICHT LEUCHTET</span><span>✦</span></div><h2>Ein Zuhause zwischen den Sternen.</h2><p>Die Geschichte von Lyra ist erzählt. Deine Station wächst weiter. Forsche zu Ende, erweitere den Hafen und sammle Erinnerungen.</p><button class="primary-button" data-panel="victory">Deine Geschichte<span>→</span></button>';return;}
  $('#mission-card').classList.toggle('complete',p.complete);$('#mission-card').innerHTML='<div class="mission-meta"><span>DEIN NÄCHSTES KAPITEL</span><span>'+String(game.missionIndex+1).padStart(2,'0')+' / '+MISSIONS.length+'</span></div><h2>'+esc(m.title)+'</h2><p>'+esc(m.description)+'</p><div class="mission-progress"><span style="width:'+p.value/p.total*100+'%"></span></div><div class="mission-progress-label"><span>'+(p.complete?'BEREIT ZUM ABSCHLIESSEN':'SCHRITT FÜR SCHRITT')+'</span><span>'+p.value+' / '+p.total+'</span></div><div class="mission-reward">DEIN KLEINER RÜCKENWIND<div class="cost-row">'+costHTML(m.reward,{gain:true,sign:true})+'</div></div>'+(p.complete?'<button class="primary-button" data-action="claim">Kapitel abschließen'+icon('check')+'</button>':'<button class="hint-button" data-action="mission-hint">Zeig mir den nächsten Schritt'+icon('arrow')+'</button>');
}
function renderVisitor(force=false){const e=currentEvent(game),hash=e?.id||'';if(hash===lastVisitor&&!force)return;lastVisitor=hash;$('#visitor-card').hidden=!e;if(!e)return;$('#visitor-card').innerHTML='<span class="eyebrow">✧ BESUCH AM HAFEN</span><h2>'+esc(e.title)+'</h2><small>'+esc(e.speaker)+'</small><p>'+esc(e.text)+'</p>'+e.choices.map((c,i)=>'<button class="visitor-choice afford-button" data-choice="'+i+'" data-cost="'+costAttr(c.cost)+'">'+esc(c.label)+(c.cost?'<span class="cost-row">'+costHTML(c.cost)+'</span>':'')+'</button>').join('');}
function flightsHTML(){return game.expeditions.map(e=>{const sector=SECTORS.find(s=>s.id===e.sectorId),crew=game.crew.find(c=>c.id===e.crewId);return '<div class="flight-item" data-flight="'+e.id+'"><strong>'+esc(sector.name)+'</strong><span><span>'+esc(crew.name)+'</span><span data-flight-time>'+duration(e.endsAt-game.time)+'</span></span><div class="flight-bar"><span data-flight-progress style="width:'+Math.min(100,(game.time-e.startsAt)/(e.endsAt-e.startsAt)*100)+'%"></span></div></div>';}).join('');}
function renderFlights(force=false){const hash=game.expeditions.map(e=>e.id).join(',');if(hash!==lastFlights||force){lastFlights=hash;$('#flight-card').hidden=game.expeditions.length===0;$('#flight-card').innerHTML='<span class="eyebrow">UNTERWEGS NACH HAUSE</span>'+flightsHTML();if(panel==='map')renderPanel();}$$('[data-flight]').forEach(el=>{const e=game.expeditions.find(e=>e.id===el.dataset.flight);if(!e)return;el.querySelector('[data-flight-time]').textContent=duration(e.endsAt-game.time);el.querySelector('[data-flight-progress]').style.width=Math.min(100,(game.time-e.startsAt)/(e.endsAt-e.startsAt)*100)+'%';});}
function renderContracts(force=false){const hash=game.contracts.join(',');if(hash===lastContracts&&!force)return;lastContracts=hash;$('#contracts').innerHTML=game.contracts.map((id,slot)=>{const c=CONTRACTS[id];return '<div class="contract-item"><div class="contract-name"><span>'+esc(c.name)+'</span><button '+affordAttrs(c.cost)+' data-contract="'+slot+'" title="'+esc(c.text)+'">Liefern →</button></div><div class="contract-exchange">'+costHTML(c.cost)+'<span>→</span>'+costHTML(c.gain,{gain:true})+'</div></div>';}).join('');}
function renderCrewPreview(force=false){const e=economy(game),hash=game.crew.length+':'+e.morale+':'+e.idle;if(hash===lastCrew&&!force)return;lastCrew=hash;$('#crew-preview').innerHTML='<div class="crew-avatars">'+game.crew.slice(0,4).map(portrait).join('')+'</div><button data-panel="crew"><strong>'+game.crew.length+' Geschichten an Bord.</strong><small>'+e.idle+' frei · '+e.morale+' % Stimmung</small></button><span>→</span>';}
function refreshAffordability(){
  $$('[data-resource-key]').forEach(el=>el.classList.toggle('insufficient',(game.resources[el.dataset.resourceKey]||0)+1e-8<Number(el.dataset.amount)));
  $$('.afford-button').forEach(b=>{try{b.disabled=b.dataset.blocked==='true'||!canAfford(game,JSON.parse(decodeURIComponent(b.dataset.cost)));}catch{b.disabled=true;}});
  $$('[data-afford-dot]').forEach(el=>{try{el.hidden=!canAfford(game,JSON.parse(decodeURIComponent(el.dataset.affordDot)));}catch{el.hidden=true;}});
}
function render(force=false){renderResources();if(force||lastTechCount!==game.techs.length){lastTechCount=game.techs.length;renderBuildList();}renderMission(force);renderVisitor(force);renderFlights(force);renderContracts(force);renderCrewPreview(force);refreshAffordability();if(panel==='social')socialUI.refresh();}

const PANEL_TITLES={social:['FREUNDESRANGLISTE & STATIONSVERGLEICH','Zusammen sieht man weiter.'],research:['FORSCHUNG & MÖGLICHKEITEN','Neugier bringt uns weiter.'],crew:['DIE MENSCHEN HINTER DEM HAFEN','Niemand baut allein.'],map:['LYRA-SEKTOR / STERNENKARTE','Das All ist nicht leer.'],log:['DAS STATIONSLOGBUCH','Was bleibt, sind Geschichten.'],trade:['FÜR ALLES GIBT ES EINEN NACHBARN','Tauschhandel am Hafen.'],achievements:['DEINE KLEINEN MEILENSTEINE','Erinnerungen an die Reise.'],settings:['DEIN SPIEL. DEIN TEMPO.','Alles an seinem Platz.'],help:['WILLKOMMEN AN BORD','Ein paar gute Hinweise.'],victory:['DAS LETZTE KAPITEL IST EIN ANFANG','Wir sehen euer Licht.'],offline:['WILLKOMMEN ZURÜCK','Dein Hafen war fleißig.'],recycle:['EIN BISSCHEN PLATZ FÜR NEUES','Dieses Modul recyceln?'],import:['ZURÜCK AN EINEN ANDEREN ORT','Spielstand laden?']};
let offlineReport=null;
function openPanel(name){if(!PANEL_TITLES[name])return;if(salvageRun?.running)return;panel=name;$('#dialog-eyebrow').textContent=PANEL_TITLES[name][0];$('#dialog-title').textContent=PANEL_TITLES[name][1];renderPanel();if(!$('#panel-dialog').open)$('#panel-dialog').showModal();document.body.classList.remove('mobile-build-open');$('.station-tab').classList.remove('active');$$('.main-tabs [data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));}
function closePanel(){if($('#panel-dialog').open)$('#panel-dialog').close();panel=null;$('.station-tab').classList.add('active');$$('.main-tabs [data-panel]').forEach(b=>b.classList.remove('active'));}
function researchPanel(){return '<p class="dialog-intro">Wissen entsteht in besetzten Laboren und auf Expeditionen. Jede neue Idee öffnet etwas Konkretes. <strong>'+game.techs.length+' von '+TECHS.length+' Technologien</strong> sind erforscht.</p><div class="panel-grid">'+TECHS.map(t=>{const done=game.techs.includes(t.id),deps=t.requires.every(id=>game.techs.includes(id));return '<article class="tech-card '+(done?'researched':deps?'available':'locked')+'"><div class="tech-card-top">'+icon(t.icon)+'<h3>'+esc(t.name)+'</h3></div><p>'+esc(t.description)+'</p>'+(done?'<span class="researched-label">'+icon('check')+'BEREITS ERFORSCHT</span>':!deps?'<div class="tech-prerequisite">'+icon('lock')+'<span>Zuerst: '+t.requires.filter(id=>!game.techs.includes(id)).map(id=>esc(TECHS.find(t=>t.id===id).name)).join(' + ')+'</span></div>':'<div class="cost-row">'+costHTML(t.cost)+'</div><button '+affordAttrs(t.cost)+' data-research="'+t.id+'">Erforschen'+icon('spark')+'</button>')+'</article>';}).join('')+'</div>';}
function crewPanel(){const e=economy(game),next=CREW_POOL[game.crew.length%CREW_POOL.length];return '<p class="dialog-intro">Ingenieure sind besonders gut an Bohrern und Raffinerien, Forschende in Laboren, Händler im Kontor. Piloten reisen schneller und bringen mehr Fracht heim. <strong>Jede Person hat genau einen Dienst.</strong></p><div class="crew-summary"><span>AN BORD <strong>'+game.crew.length+' / '+e.housing+'</strong></span><span>FREI <strong>'+e.idle+'</strong></span><span>STIMMUNG <strong>'+e.morale+' %</strong></span><button '+affordAttrs(hireCost(game),game.crew.length>=housing(game)||game.crew.length>=24)+' data-action="hire">'+icon('plus')+'Crew verstärken · '+num(hireCost(game).credits)+' Cr</button></div>'+(game.crew.length>=housing(game)?'<p class="note-small">Baue ein Wohnmodul, damit neue Crew-Mitglieder ankommen können.</p>':'<p class="note-small">Nächste Ankunft: '+esc(next.name)+' · '+esc(next.role)+'. Die Überfahrt kostet Credits; danach gibt es keine laufenden Gehaltskosten.</p>')+'<div class="panel-grid">'+game.crew.map(c=>{const job=crewAssignment(game,c.id),flight=game.expeditions.find(e=>e.crewId===c.id),threshold=c.level===1?600:c.level===2?2200:6000;return '<article class="crew-card"><div class="crew-card-head">'+portrait(c)+'<div><h3>'+esc(c.name)+'</h3><small>'+esc(c.role)+'</small></div><span class="crew-rank">LV '+c.level+'</span></div><div class="crew-trait">'+esc(c.trait)+'</div><p class="crew-quote">'+esc(c.description)+'</p><div class="crew-job">'+(flight?'→ Unterwegs: '+esc(SECTORS.find(z=>z.id===flight.sectorId).name):job?'Im Dienst: '+esc(MODULES[job.type].name):'Freier Dienst · Bereit für eine neue Aufgabe')+'</div><div class="crew-bonus">'+({engineer:'+25 % an Bohrern und Raffinerien',scientist:'+25 % an Laboren und Sternwarten',trader:'+25 % Credits im Handelskontor',pilot:'18 % kürzere Flüge · bessere Funde'})[c.skill]+'</div>'+(!flight?'<label class="sr-only" for="crew-job-'+c.id+'">Aufgabe für '+esc(c.name)+'</label><select id="crew-job-'+c.id+'" data-crew-job="'+c.id+'"><option value="">Freier Dienst</option>'+game.modules.filter(m=>MODULES[m.type].workers).map(m=>'<option value="'+m.id+'"'+(job?.id===m.id?' selected':'')+'>'+esc(MODULES[m.type].name)+' ['+m.x+'/'+m.y+']'+(m.assigned&&m.assigned!==c.id?' · besetzt':'')+'</option>').join('')+'</select>':'')+'<div class="xp-bar" title="Erfahrung: '+num(c.xp)+'"><span style="width:'+Math.min(100,c.xp/threshold*100)+'%"></span></div></article>';}).join('')+'</div>';}
function mapPanel(){const available=game.crew.filter(c=>!crewAway(game,c.id)).sort((a,b)=>(b.skill==='pilot'?1:0)-(a.skill==='pilot'?1:0));return '<p class="dialog-intro">Jede Andockbucht öffnet einen Flugplatz pro Stufe. Deine Crew kommt immer zurück; bei Zwischenfällen ist lediglich die Fracht kleiner. <strong>Signalfragmente: '+game.fragments.length+' / 3.</strong> Die erste erfolgreiche Reise zu jedem markierten Ziel bringt sein Fragment sicher mit.</p><div class="map-visual"><svg class="map-paths" viewBox="0 0 100 100" preserveAspectRatio="none"><line x1="9" y1="51" x2="24" y2="60"/><line x1="24" y1="60" x2="43" y2="30"/><line x1="43" y1="30" x2="62" y2="58"/><line x1="62" y1="58" x2="82" y2="29"/><line x1="62" y1="58" x2="79" y2="79"/></svg><span class="map-node home"><span class="node-dot"></span>'+esc(game.name)+'</span>'+SECTORS.map(z=>'<button class="map-node '+(!game.techs.includes(z.tech)?'locked':'active')+'" style="left:'+z.x+'%;top:'+z.y+'%;color:'+z.color+'" data-map-focus="'+z.id+'"><span class="node-dot"></span>'+esc(z.name)+'</button>').join('')+'</div>'+(game.expeditions.length?'<div class="active-flights"><h3>UNTERWEGS · '+game.expeditions.length+' / '+expeditionCapacity(game)+' FLUGPLÄTZE</h3>'+flightsHTML()+'</div>':'')+(expeditionCapacity(game)===0?'<p class="storage-notice">Deine Station braucht zuerst eine Andockbucht. Die Orbitalnavigation öffnet danach die ersten Routen.</p>':'')+'<div class="panel-grid">'+SECTORS.map(z=>{const unlocked=game.techs.includes(z.tech),defaultCrew=available[0];return '<article class="sector-card '+(!unlocked?'locked':'')+'" id="sector-'+z.id+'"><h3><span style="color:'+z.color+'">✦</span>'+esc(z.name)+'</h3><span class="sector-subtitle">'+esc(z.subtitle)+'</span><p>'+esc(z.description)+'</p>'+(z.fragment?'<span class="fragment-tag '+(game.fragments.includes(z.id)?'found':'')+'">'+icon(game.fragments.includes(z.id)?'check':'wave')+(game.fragments.includes(z.id)?'Signalfragment gefunden':'Hier wartet ein Signalfragment')+'</span>':'')+'<div class="sector-meta"><span>'+icon('clock')+'<span data-sector-duration="'+z.id+'">'+duration(expeditionDuration(game,z,defaultCrew))+'</span></span><span>'+icon('ship')+'Risiko '+num(z.risk*100)+' %*</span></div><div class="cost-row">'+costHTML(z.cost)+'</div>'+(unlocked?'<div class="flight-choice"><label class="sr-only" for="pilot-'+z.id+'">Crew für '+esc(z.name)+'</label><select id="pilot-'+z.id+'" aria-label="Crew für '+esc(z.name)+'">'+(available.length?available.map(c=>'<option value="'+c.id+'">'+esc(c.name)+(c.skill==='pilot'?' · Pilot':'')+(crewAssignment(game,c.id)?' · verlässt Arbeitsplatz':'')+'</option>').join(''):'<option value="">Alle sind unterwegs</option>')+'</select><button '+affordAttrs(z.cost,!available.length||game.expeditions.length>=expeditionCapacity(game))+' data-send="'+z.id+'">Los →</button></div>':'<button class="small-button" data-panel="research" style="margin-top:16px">'+icon('lock')+esc(TECHS.find(t=>t.id===z.tech).name)+'</button>')+'<div class="risk-note">* Bei einem Zwischenfall kommt weniger Fracht an. Piloten senken das Risiko deutlich; niemand geht verloren.</div></article>';}).join('')+'</div>';}
function tradePanel(){return '<p class="dialog-intro">Die Versorgungslinie ist immer offen – auch wenn dein letzter Bohrer gerade stillsteht. Lagerplätze sind begrenzt; baue bei Bedarf ein Frachtdepot.</p><div class="market-grid"><article class="market-card">'+icon('alloy')+'<h3>20 Legierung</h3><p>Ein paar Platten für den nächsten Anfang.</p><button '+affordAttrs({credits:45})+' data-trade="alloy">Für 45 Credits kaufen</button></article><article class="market-card">'+icon('gem')+'<h3>8 Kristalle</h3><p>Seltenes Material von Nalas Route.</p><button '+affordAttrs({credits:65})+' data-trade="crystal">Für 65 Credits kaufen</button></article><article class="market-card">'+icon('coin')+'<h3>35 Credits</h3><p>25 Legierung gegen ein kleines Budget.</p><button '+affordAttrs({alloy:25})+' data-trade="sell">25 Legierung verkaufen</button></article></div><h3 class="panel-subtitle">Dein aktuelles Lager</h3><div class="cost-row">'+costHTML(game.resources,{gain:true})+'</div><p class="note-small">Der Handel ist Spielmechanik. Alle Währungen werden ausschließlich im Spiel verdient; es gibt keine Käufe mit echtem Geld.</p>';}
function logPanel(){return '<p class="dialog-intro">Die letzten 70 Einträge deiner Reise. Kleine Begegnungen machen aus Koordinaten einen Ort.</p><div class="log-list">'+game.log.map(l=>'<article class="log-entry '+esc(l.type)+'"><time>TAG '+String(Math.floor(l.time/180)+1).padStart(2,'0')+'<br>'+duration(l.time%180)+'</time><div><h3>'+esc(l.title)+'</h3><p>'+esc(l.text)+'</p></div></article>').join('')+'</div>';}
function achievementsPanel(){return '<p class="dialog-intro">Keine Eile, keine täglichen Pflichten. Nur kleine Erinnerungen an das, was du hier aufgebaut hast. <strong>'+game.achievements.length+' / '+ACHIEVEMENTS.length+' freigeschaltet.</strong></p><div class="panel-grid">'+ACHIEVEMENTS.map(a=>'<article class="achievement-card '+(game.achievements.includes(a.id)?'earned':'')+'">'+icon(game.achievements.includes(a.id)?'trophy':'lock')+'<div><h3>'+esc(a.title)+'</h3><p>'+esc(a.description)+'</p></div></article>').join('')+'</div>';}
function settingsPanel(){return '<div class="settings-section"><h3>Ein Name für deinen Hafen</h3><form class="rename-form" id="rename-form"><label class="sr-only" for="rename-station">Stationsname</label><input id="rename-station" maxlength="24" value="'+esc(game.name)+'" required><button class="small-button" type="submit">Umbenennen</button></form></div><div class="settings-section"><h3>Atmosphäre</h3><div class="setting-row"><span>Sanfte Synth-Klänge & Spielgeräusche</span><button class="toggle-button" data-action="sound" aria-pressed="'+prefs.sound+'">'+(prefs.sound?'An':'Aus')+'</button></div><p>Ton startet erst nach deinem Klick. Spieltempo 1×, 2× und 4× sowie Pause findest du jederzeit unten rechts.</p></div><div class="settings-section"><h3>Dein Spielstand gehört dir</h3><p>Automatische Speicherung alle 20 Sekunden und nach wichtigen Aktionen. Alles bleibt in diesem Browser. Exportiere eine Sicherung, bevor du Browserdaten löschst oder das Gerät wechselst. Beim Import wird der aktuelle Stand erst nach Bestätigung ersetzt.</p>'+(!storageOkay?'<p class="storage-notice">Dieser Browser erlaubt keine dauerhafte Speicherung. Bitte exportiere vor dem Schließen.</p>':'')+'<div class="settings-buttons"><button class="small-button" data-action="export">'+icon('download')+'Spielstand exportieren</button><button class="small-button" data-action="import">'+icon('upload')+'Spielstand importieren</button><button class="small-button" data-action="backup">'+icon('refresh')+'Vorherigen Stand laden</button></div><p class="note-small">Deine Station produziert in Abwesenheit bis zu 30 Minuten weiter, mit dem normalen Tempo 1×. Im Pausenmodus bleibt auch die Offline-Zeit stehen.</p></div><div class="settings-section"><h3>Noch einmal ganz klein anfangen</h3><p>Eine neue Reise ersetzt die aktuelle Station. Exportiere deinen Spielstand, wenn du sie behalten möchtest.</p><button class="small-button danger" data-action="ask-new">Neue Station gründen</button><div id="new-confirm" class="danger-confirm" hidden><p>Das startet eine neue Station. Dein aktueller Ausbau wird ersetzt. Wirklich neu anfangen?</p><div class="settings-buttons"><button class="small-button" data-action="export">Erst exportieren</button><button class="primary-button" data-action="new-game">Ja, neue Reise beginnen</button></div></div></div><p class="note-small">STERNENHAFEN 1.1 · Ein eigenständiges Browser-Spiel. Keine Anmeldung, keine Werbung, keine externen Spieldienste. Grafiken und Klang entstehen direkt im Browser.</p>';}
function helpPanel(){return '<p class="dialog-intro">Sternenhafen ist ein ruhiges Aufbauspiel mit kleinen Ausflügen. Es gibt keinen Zeitdruck und keinen verlorenen Spielstand durch eine gescheiterte Expedition.</p><div class="help-grid"><div><h3>Eine Station bauen</h3><p>Wähle links ein Modul, dann ein markiertes Nachbarfeld. Alle Module müssen direkt mit dem Rest der Station verbunden bleiben. Ein Klick auf ein gebautes Modul zeigt Ausbauten, Arbeitsplätze und Recycling.</p><p>Auf dem Handy öffnet „Bauen“ das Baumenü. Die Stationsansicht lässt sich mit einem Finger verschieben.</p></div><div><h3>Versorgung & Crew</h3><p>Solarsegel liefern Energie. Bei einem Defizit wird die Produktion langsamer, statt deine Station zu zerstören. Bohrer, Labore, Raffinerien, Kontore und Sternwarten brauchen jeweils eine Person. Neue Crew stellst du im Crew-Fenster ein.</p><p>Gärten und die Lounge heben die Stimmung und damit die Leistung. Wohnmodule schaffen Plätze, aber keine neue Crew von selbst.</p></div><div><h3>Expeditionen & Bergung</h3><p>Andockbucht und Orbitalnavigation öffnen die ersten Routen. Wähle eine Person und schicke sie los. Die drei markierten Ziele bringen bei der ersten Rückkehr garantiert ein Signalfragment.</p><p>Oder fliege selbst: Das Bergungsschiff sammelt Fracht in 45 Sekunden. Bewegen mit WASD, Pfeilen oder Finger; der Laser feuert automatisch. Auch ein beschädigtes Schiff kehrt mit seiner Fracht zurück.</p></div><div><h3>Gemeinsam vergleichen</h3><p>Öffne „Rangliste“ oder drücke 6. Kopiere deinen Stationslink und teile ihn mit Freunden. Ihren Antwortlink kannst du dort hinzufügen und beide Stationen direkt vergleichen.</p><p>Stationsbau, Forschung, Entdeckungen und deine beste Bergung ergeben die Punkte. Fremde Einträge zeigen ihren Stand beim Teilen. Ein neuer Link derselben Station aktualisiert den Vergleich; deine eigene Station wird aktuell angezeigt.</p></div><div><h3>Ein paar praktische Tasten</h3><ul><li><kbd>1</kbd> Station · <kbd>2</kbd> Sternenkarte</li><li><kbd>3</kbd> Forschung · <kbd>4</kbd> Crew · <kbd>5</kbd> Logbuch · <kbd>6</kbd> Rangliste</li><li><kbd>B</kbd> Baumenü · <kbd>Esc</kbd> Abbrechen</li><li><kbd>Leertaste</kbd> Pause / Fortsetzen</li><li>Beim Bauen: <kbd>Pfeile</kbd> + <kbd>Enter</kbd></li><li>Ziehen: Ansicht verschieben · Mausrad: Zoom</li></ul></div><div><h3>Wenn Material fehlt</h3><p>Die Zentrale liefert immer ein kleines Budget. Unter „Handel“ bekommst du Legierung und Kristalle. Ein kostenloser Bergungsflug hilft ebenfalls. So kommst du auch nach einem ungünstigen Ausbau wieder weiter.</p></div><div><h3>Dein Ziel</h3><p>Die Kapitel führen von deinem ersten Solarsegel bis zum Lyra-Leuchtfeuer. Dafür brauchst du drei Fragmente, Forschung und einen gut versorgten Hafen. Nach dem Abschluss kannst du frei weiterbauen.</p></div></div>';}
function victoryPanel(){return '<div class="victory-panel"><div class="victory-star">✦</div><h3>Ein Hafen in der Dunkelheit.</h3><p>'+esc(game.name)+' ist mehr als ein Punkt auf der Karte geworden. Zwischen Stahl, Grün und leuchtenden Fenstern haben Menschen einen Ort gefunden, an dem sie ankommen können.</p><p>Das Leuchtfeuer antwortet.<br><strong>„Wir sehen euch. Wir kommen nach Hause.“</strong></p><div class="victory-stats"><span><strong>'+game.modules.length+'</strong>MODULE</span><span><strong>'+game.crew.length+'</strong>GESCHICHTEN</span><span><strong>'+game.stats.expeditions+'</strong>ENTDECKUNGEN</span><span><strong>'+game.achievements.length+'</strong>ERINNERUNGEN</span></div><button class="primary-button" data-close>Die Geschichte geht weiter<span>→</span></button><p class="note-small">Deine Station bleibt bestehen. Es gibt noch neue Ausbauten, weitere Technologien und eine ganze Menge Alltag zwischen den Sternen.</p></div>';}
function renderPanel(){if(!panel)return;const renderers={social:()=>socialUI.render(),research:researchPanel,crew:crewPanel,map:mapPanel,log:logPanel,trade:tradePanel,achievements:achievementsPanel,settings:settingsPanel,help:helpPanel,victory:victoryPanel,
  offline:()=>'<div class="offline-summary"><h3>Schön, dass du wieder da bist.</h3><p>Deine Crew hat '+duration(offlineReport?.seconds||0)+' Minuten und Sekunden weitergearbeitet. Berücksichtigt werden höchstens 30 Minuten. Das Lager begrenzt die gesammelten Vorräte.</p><div class="cost-row">'+costHTML(offlineReport?.rewards||{},{gain:true,sign:true})+'</div></div><p class="dialog-intro">Laufende Expeditionen sind in dieser Zeit ebenfalls weitergeflogen. Neue Besucher warten erst nach deiner Rückkehr an.</p><button class="primary-button" data-close>Zurück an Bord<span>→</span></button>',
  recycle:()=>{const m=game.modules.find(m=>m.id===recycleId);if(!m)return '<p>Dieses Modul steht nicht mehr.</p>';const refund=Object.fromEntries(Object.entries(MODULES[m.type].cost).map(([k,n])=>[k,Math.floor(n*.55)]));return '<p class="dialog-intro">Du recycelst <strong>'+esc(MODULES[m.type].name)+'</strong> auf Stufe '+m.level+'. Du erhältst 55 % der ursprünglichen Baukosten zurück; Ausbaukosten werden nicht erstattet. Die Crew bleibt an Bord.</p><div class="cost-row">'+costHTML(refund,{gain:true,sign:true})+'</div><p class="note-small">Andere Module müssen verbunden und alle Crew-Mitglieder untergebracht bleiben.</p><div class="settings-buttons" style="margin-top:24px"><button class="small-button" data-close>Behalten</button><button class="small-button danger" data-action="confirm-recycle">'+icon('trash')+'Modul recyceln</button></div>';},
  import:()=>'<p class="dialog-intro">Du lädst <strong>'+esc(pendingImport?.name||'')+'</strong> mit '+(pendingImport?.modules.length||0)+' Modulen und '+(pendingImport?.crew.length||0)+' Crew-Mitgliedern. Der aktuelle Stand wird ersetzt und zuvor als Browser-Sicherung gespeichert.</p><div class="settings-buttons"><button class="small-button" data-close>Abbrechen</button><button class="primary-button" data-action="confirm-import">Diesen Spielstand laden<span>→</span></button></div>'};
  $('#dialog-body').innerHTML=renderers[panel]?.()||'';refreshAffordability();
}

function setSound(){prefs.sound=!prefs.sound;sound.setEnabled(prefs.sound);try{localStorage.setItem(PREFS,JSON.stringify(prefs));}catch{}renderSound();if(panel==='settings')renderPanel();}
function renderSound(){$('#sound-button').innerHTML=icon(prefs.sound?'volume':'mute');$('#sound-button').setAttribute('aria-label',prefs.sound?'Ton ausschalten':'Ton einschalten');$('#sound-button').setAttribute('aria-pressed',String(prefs.sound));$('#sound-button').title=prefs.sound?'Ton ausschalten':'Ton einschalten';}
function exportSave(){const blob=new Blob([serialize(game)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sternenhafen-'+game.name.replace(/[^a-zA-Z0-9_-]/g,'_')+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Ein Stück Zuhause zum Mitnehmen','Dein Spielstand wird als JSON-Datei exportiert.');}
function loadGame(next){game=next;game.paused=false;buildType=null;selectedId=null;renderer.buildType=null;renderer.selected=null;$('#build-hint').hidden=true;$('#inspector').hidden=true;renderer.fit();lastMission='';lastVisitor='';lastFlights='';lastCrew='';lastContracts='';lastTechCount=-1;closePanel();changed();}
function openSalvage(){if(!salvageReady(game)){toast('Ein kurzer Boxenstopp','Das Schiff tankt noch '+duration(45-(game.time-game.lastSalvage))+'.');return;}closePanel();cancelBuild();$('#salvage-intro').hidden=false;$('#salvage-result').hidden=true;$('#salvage-health').textContent='♡ ♡ ♡';$('#salvage-crates').textContent='00';$('#salvage-score').textContent='0000';$('#salvage-timer').textContent='00:45';$('#salvage-dialog').showModal();salvageRun?.destroy();salvageRun=new SalvageRun($('#salvage-canvas'),{sound,onHud:h=>{$('#salvage-health').textContent='♥ '.repeat(h.health)+'♡ '.repeat(3-h.health);$('#salvage-crates').textContent=String(h.crates).padStart(2,'0');$('#salvage-score').textContent=String(h.score).padStart(4,'0');$('#salvage-timer').textContent=duration(h.time);},onFinish:r=>{const res=awardSalvage(game,r.crates,r.score);if(!res.ok){toast('Bergung bereits erfasst',res.error,'error');return;}$('#salvage-intro').hidden=true;$('#salvage-result').hidden=false;$('#salvage-result').innerHTML='<span class="eyebrow">WILLKOMMEN ZURÜCK AN BORD</span><h3>'+(r.health>0?'Nicht alles, was treibt, ist verloren.':'Die Fracht ist sicher. Du auch.')+'</h3><p>'+(r.health>0?'Ein guter Flug. Dein Hafen kann das gebrauchen.':'Ein paar Kratzer. Ein paar gute Funde. Das Schiff wird schon wieder.')+'</p><div class="salvage-score-summary"><span><strong>'+r.crates+'</strong>FRACHTSTÜCKE</span><span><strong>'+num(r.score)+'</strong>PUNKTE</span><span><strong>'+game.stats.bestSalvage+'</strong>BESTE BERGUNG</span></div><div class="salvage-rewards">'+costHTML(res.rewards,{gain:true,sign:true})+'</div><button class="primary-button" data-action="exit-salvage">Zurück zum Hafen<span>→</span></button><small>Die Fracht ist bereits in deinem Lager. Das Schiff tankt für den nächsten Flug.</small>';sound.play('claim');changed();}});}

document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b||b.disabled)return;sound.unlock();
  if(b.dataset.panel){openPanel(b.dataset.panel);return;}
  if(b.hasAttribute('data-close')){closePanel();return;}
  if(b.dataset.build){selectBuild(b.dataset.build);return;}
  if(b.hasAttribute('data-build-group')){buildGroup=b.dataset.buildGroup;$$('[data-build-group]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderBuildList();refreshAffordability();return;}
  if(b.dataset.upgrade){const m=game.modules.find(m=>m.id===b.dataset.upgrade);if(result(upgrade(game,b.dataset.upgrade),'Ein bisschen mehr möglich.','upgrade')){renderer.effect(m.x,m.y,'Stufe '+m.level);renderInspector();}return;}
  if(b.dataset.recycle){recycleId=b.dataset.recycle;openPanel('recycle');return;}
  if(b.dataset.research){if(result(research(game,b.dataset.research),null,'research'))renderPanel();return;}
  if(b.dataset.send){const crewId=$('#pilot-'+b.dataset.send).value;if(result(sendExpedition(game,b.dataset.send,crewId),'Gute Reise. Wir lassen das Licht an.','launch'))renderPanel();return;}
  if(b.dataset.trade){if(result(trade(game,b.dataset.trade),'Ein guter Tausch.','coin'))renderPanel();return;}
  if(b.hasAttribute('data-contract')){result(deliverContract(game,Number(b.dataset.contract)),null,'coin');return;}
  if(b.hasAttribute('data-choice')){result(chooseEvent(game,Number(b.dataset.choice)),null,'claim');return;}
  if(b.dataset.mapFocus){$('#sector-'+b.dataset.mapFocus)?.scrollIntoView({behavior:'smooth',block:'nearest'});return;}
  if(b.dataset.speed){game.speed=Number(b.dataset.speed);changed();return;}
  const action=b.dataset.action;
  if(action==='claim'){result(claimMission(game),null,'claim');return;}
  if(action==='mission-hint'){missionHint();return;}
  if(action==='station'){closePanel();$('#station').scrollIntoView({behavior:'smooth',block:'nearest'});return;}
  if(action==='hire'){if(result(hire(game),'Eine neue Geschichte an Bord.','claim'))renderPanel();return;}
  if(action==='cancel-build'){cancelBuild();return;}
  if(action==='close-inspector'){selectedId=null;renderer.selected=null;$('#inspector').hidden=true;return;}
  if(action==='confirm-recycle'){const res=recycle(game,recycleId);if(result(res,'Platz für eine neue Idee.')){selectedId=null;renderer.selected=null;$('#inspector').hidden=true;closePanel();}return;}
  if(action==='zoom-in'){renderer.zoom(1.18);return;}
  if(action==='zoom-out'){renderer.zoom(1/1.18);return;}
  if(action==='fit'){renderer.fit();return;}
  if(action==='grid'){renderer.grid=!renderer.grid;b.setAttribute('aria-pressed',String(renderer.grid));return;}
  if(action==='pause'){game.paused=!game.paused;changed();return;}
  if(action==='sound'){setSound();return;}
  if(action==='toggle-build'){document.body.classList.toggle('mobile-build-open');return;}
  if(action==='close-build'){document.body.classList.remove('mobile-build-open');return;}
  if(action==='salvage'){openSalvage();return;}
  if(action==='start-salvage'){$('#salvage-intro').hidden=true;salvageRun?.start();return;}
  if(action==='exit-salvage'){if(salvageRun?.running){salvageRun.finish();return;}salvageRun?.destroy();salvageRun=null;$('#salvage-dialog').close();return;}
  if(action==='export'){exportSave();return;}
  if(action==='import'){$('#import-file').click();return;}
  if(action==='backup'){try{const backup=localStorage.getItem(BACKUP);if(!backup)throw new Error('Es gibt noch keinen vorherigen Sicherungsstand.');pendingImport=restore(backup);openPanel('import');}catch(err){toast('Sicherung nicht verfügbar',err.message,'error');}return;}
  if(action==='confirm-import'){if(pendingImport){loadGame(pendingImport);pendingImport=null;toast('Zurück an Bord',game.name+' ist geladen.');}return;}
  if(action==='ask-new'){$('#new-confirm').hidden=false;$('#new-confirm').scrollIntoView({behavior:'smooth',block:'nearest'});return;}
  if(action==='new-game'){loadGame(createGame('Aurelia'));toast('Jede große Geschichte beginnt klein','Willkommen zurück am Anfang.');return;}
});
document.addEventListener('change',e=>{
  if(e.target.id?.startsWith('pilot-')){const id=e.target.id.slice(6),z=SECTORS.find(z=>z.id===id),c=game.crew.find(c=>c.id===e.target.value);const label=$('[data-sector-duration="'+id+'"]');if(label&&z)label.textContent=duration(expeditionDuration(game,z,c));}
  if(e.target.dataset.assign){if(result(assign(game,e.target.dataset.assign,e.target.value),'Dienstplan aktualisiert.'))renderInspector();}
  if(e.target.dataset.crewJob){const crewId=e.target.dataset.crewJob,moduleId=e.target.value;if(!moduleId){const job=crewAssignment(game,crewId);if(job)assign(game,job.id,null);changed();renderPanel();}else if(result(assign(game,moduleId,crewId),'Ein neuer Arbeitsplatz.'))renderPanel();}
});
document.addEventListener('submit',e=>{if(e.target.id==='rename-form'){e.preventDefault();const name=$('#rename-station').value.trim().slice(0,24);if(!name)return;game.name=name;changed();toast('Ein guter Name',name+' steht jetzt auf der Sternenkarte.');}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>500000)throw new Error('Diese Datei ist zu groß für einen Sternenhafen-Spielstand.');const next=restore(await file.text());pendingImport=next;openPanel('import');}catch(err){toast('Der Spielstand wurde nicht verändert',err.message||'Die Datei ist nicht lesbar.','error');}e.target.value='';});
// A queued close event must not clear a dialog already reopened by a new invitation.
$('#panel-dialog').addEventListener('close',()=>{if($('#panel-dialog').open)return;panel=null;$('.station-tab').classList.add('active');$$('.main-tabs [data-panel]').forEach(b=>b.classList.remove('active'));});
$('#panel-dialog').addEventListener('click',e=>{if(e.target===$('#panel-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
$('#salvage-dialog').addEventListener('cancel',e=>{if(salvageRun?.running){e.preventDefault();salvageRun.finish();}else{salvageRun?.destroy();salvageRun=null;}});
document.addEventListener('keydown',e=>{if(!started||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if($('#salvage-dialog').open||$('#panel-dialog').open)return;if(e.key==='Escape'){if(document.body.classList.contains('mobile-build-open'))document.body.classList.remove('mobile-build-open');else if(buildType){e.preventDefault();cancelBuild();}return;}const panels={'2':'map','3':'research','4':'crew','5':'log','6':'social'};if(panels[e.key]){e.preventDefault();openPanel(panels[e.key]);}else if(e.key==='1'){closePanel();}else if(e.key.toLowerCase()==='b'){if(window.innerWidth<=620)document.body.classList.toggle('mobile-build-open');else $('#build-list button')?.focus();}else if(e.key===' '&&e.target.tagName!=='BUTTON'){e.preventDefault();game.paused=!game.paused;changed();}else if(e.key==='+')renderer.zoom(1.15);else if(e.key==='-')renderer.zoom(1/1.15);});
$('#start-button').addEventListener('click',()=>{if(started)return;if(!hasSave)game.name=$('#new-station-name').value.trim().slice(0,24)||'Aurelia';offlineReport=hasSave?offlineProgress(game):null;game.paused=false;started=true;$('#welcome').hidden=true;sound.unlock();renderer.fit();render(true);save(true);if(socialUI.hasInvitation())openPanel('social');else if(offlineReport?.seconds>=30)openPanel('offline');if(!hasSave)toast('Willkommen an Bord, Captain.','Dein erstes Kapitel wartet rechts. Das Bergungsschiff ist ebenfalls bereit.');drainNotices();});
if(hasSave){$('#start-button').innerHTML='Zurück an Bord<span>→</span>';$('#name-label').hidden=true;$('#welcome .welcome-card>p').innerHTML='Dein Hafen <strong>'+esc(game.name)+'</strong> wartet auf dich.<br>'+game.modules.length+' Module. '+game.crew.length+' Geschichten. Dein Platz im All.';}
if(loadWarning){$('#welcome-error').hidden=false;$('#welcome-error').textContent=loadWarning;}
const iconTargets={'settings-button':'settings','fit-button':'fit','grid-button':'grid','mobile-build-icon':'build','station-tab-icon':'build','map-tab-icon':'orbit','research-tab-icon':'science','crew-tab-icon':'crew','log-tab-icon':'book','social-tab-icon':'trophy','trade-button':'coin','achievements-button':'trophy','help-button':'help','dialog-close':'close','salvage-close':'close'};for(const [id,name]of Object.entries(iconTargets))$('#'+id).innerHTML=icon(name);renderSound();render(true);
function frame(now){const dt=Math.min((now-lastFrame)/1000,.5);lastFrame=now;if(started&&!document.hidden){advance(game,dt*game.speed);if(now-lastUI>450){lastUI=now;render();drainNotices();save();}}renderer.draw(now);requestAnimationFrame(frame);}
requestAnimationFrame(frame);
document.addEventListener('visibilitychange',()=>{if(!started)return;if(document.hidden)save(true);else{const report=offlineProgress(game);lastFrame=performance.now();if(report.seconds>=30){offlineReport=report;if(!$('#salvage-dialog').open)openPanel('offline');}render(true);save(true);}});
window.addEventListener('pagehide',()=>save(true));
